INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(67000, 67, 0, 1, 0, 0, 0, 0, 'The Storm Peaks', 'Sturmpyk, the vrykul call it: a range of some of the tallest mountains in the world, where the cold can freeze a traveller solid and the wind can pluck them off a mountainside. The Sons of Hodir advise never coming here with fewer than two companions.\n\nThis was the home of the titans'' keepers, and nearly every mountain bears their mark. Here they built Ulduar, the greatest of their works on Azeroth.', 'warcraft.wiki.gg: Storm Peaks (introduction, Ancient times)'),
(67001, 67, 1, 1, 0, 0, 0, 0, 'The Temple of Storms', 'An open-sided titan temple on the highest mountain in Northrend, its columns rimmed with snow. Lightning cracks here even under a clear sky, while the northern lights dance across the stars. It is the sanctum of Thorim the Stormlord, one of the keepers, who has sat here brooding for a very long time.', 'warcraft.wiki.gg: Temple of Storms'),
(67002, 67, 1, 2, 0, 0, 0, 0, 'Dun Niffelem', 'A fortress of great spikes of ice and iron chains blocking off part of the Valley of Ancient Winters, home of the Sons of Hodir, a warlike clan of frost giants, under King Jokkum. Once they were friends of Thorim. That friendship ended in blood.', 'warcraft.wiki.gg: Dun Niffelem; warcraft.wiki.gg: Sons of Hodir'),
(67003, 67, 1, 3, 0, 0, 0, 0, 'Thunderfall', 'A battlefield frozen forever: giants and frost dwarves locked in combat around the crater where Thorim''s hammer, Krolmir, struck the earth, killing all nearby in an instant.', 'warcraft.wiki.gg: Sons of Hodir (History)'),
(67004, 67, 1, 4, 0, 0, 0, 0, 'Brunnhildar Village', 'The stronghold of the Hyldnir, the frost vrykul who serve Thorim. Their women are warriors, and they compete in the Hyldsmeet to decide who shall rule at Thorim''s side. Men they think good for nothing but slave labour in their mines. The Lich King sent them three emissaries; all three were dismembered. Their proto-drakes nest in the mountains above.', 'warcraft.wiki.gg: Hyldnir; warcraft.wiki.gg: Brunnhildar Village'),
(67005, 67, 1, 5, 0, 0, 0, 0, 'Valkyrion', 'A Hyldnir village whose leader, Yulda the Stormspeaker, gave it to the Lich King in return for being made a val''kyr. Its people capture proto-drakes and their eggs and drown them in the Blighted Pool to make plagued drakes. Their sisters of Brunnhildar hate them for it.', 'warcraft.wiki.gg: Valkyrion'),
(67006, 67, 1, 6, 0, 0, 0, 0, 'K3', 'An independent goblin town at the foot of the peaks, founded to get a share of the titan machines lying all over the mountains. Progress has been slow: gnolls, snobolds and magnataur keep attacking, the Hyldnir carried off all its men to their mines, and the cold freezes the motors of its flying machines.', 'warcraft.wiki.gg: K3; warcraft.wiki.gg: Sifreldar Village'),
(67007, 67, 1, 7, 0, 0, 0, 0, 'Frosthold', 'The city of the Frostborn, the whole frost dwarf race, in and around a great pit of ice atop a mountain. No road leads there; it can only be reached by air.', 'warcraft.wiki.gg: Frosthold'),
(67008, 67, 1, 8, 0, 0, 0, 0, 'Grom''arsh Crash-Site', 'A Horde camp made from the wreck of a goblin zeppelin.', 'warcraft.wiki.gg: Grom''arsh Crash-Site'),
(67009, 67, 1, 9, 0, 0, 0, 0, 'Bouldercrag''s Refuge', 'Where the earthen made their home after they were driven out of Ulduar. On the plains below, iron dwarves are building a war engine, the Iron Colossus, to turn on them.', 'warcraft.wiki.gg: Bouldercrag''s Refuge; warcraft.wiki.gg: Narvir''s Cradle'),
(67010, 67, 1, 10, 0, 0, 0, 0, 'The Terrace of the Makers', 'A complex of temples across the chasm from Ulduar, where the keepers lived and worked: Mimiron''s Temple of Invention, Hodir''s Temple of Winter, and Tyr''s Temple of Order, its keeper long absent with no sign of a struggle. The terrace is badly damaged, its walkways shattered and columns cracked. Iron dwarves fight the earthen warders who still guard it.', 'warcraft.wiki.gg: Terrace of the Makers; warcraft.wiki.gg: Temple of Order; warcraft.wiki.gg: Temple of Invention'),
(67011, 67, 1, 11, 0, 0, 0, 0, 'The Temple of Life', 'The post of the keeper Freya, empty now. The signs show a great battle against an opponent of her own size and strength. Its guardians are gone and its plants are dead.', 'warcraft.wiki.gg: Temple of Life'),
(67012, 67, 1, 12, 0, 0, 0, 0, 'Camp Tunka''lo', 'A taunka village high in the eastern mountains, so remote that the Scourge has never found it. Long ago the hero Stormhoof, brother of Chieftain Swiftspear, fought the North Wind, the elemental lord who held the peaks and the taunka in its iron grip, and weakened it before he fell.', 'warcraft.wiki.gg: Camp Tunka''lo; warcraft.wiki.gg: Storm Peaks (The North Wind)'),
(67013, 67, 1, 13, 0, 0, 0, 0, 'The Engines of the Makers', 'Vast titan machines buried in the mountains, deep shafts and engine rooms of turning gears, all parts of the Forge of Wills inside Ulduar.', 'warcraft.wiki.gg: Engine of the Makers; warcraft.wiki.gg: Loken''s Bargain'),
(67014, 67, 1, 14, 0, 0, 0, 0, 'Ulduar', 'The greatest titan complex on Azeroth, perfectly preserved in the snows. For millennia no mortal disturbed it. Since its discovery, many have wondered what it was for: a city to herald its makers'' glory, perhaps, or a vault of the titans'' own treasures.', 'warcraft.wiki.gg: Ulduar (Official Blizzard description)'),
(67050, 67, 3, 1, 0, 0, 0, 0, 'The Grief of Thorim', 'The Sons of Hodir were once friends of Thorim. Then his wife Sif was murdered, and he was made to believe that the frost giant king Arngrim was responsible. In a rage, he hurled his hammer Krolmir at Arngrim, who was in the middle of a battle with frost dwarves; the blast killed everyone around and froze the scene forever. Then Thorim fell into despair and has brooded in his temple for centuries.\n\nIt was his own brother, Loken, who killed Sif and framed the giants.', 'warcraft.wiki.gg: Sons of Hodir (History); warcraft.wiki.gg: Temple of Storms');
